import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-27（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-27-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-27-ai.md"}'),e={name:"topics/ai-system-architecture/science-daily-2026-10-27-ai.md"};function i(a,o,g,l,c,d){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-27-ai-系统架构" tabindex="-1">科学日报 · 2026-10-27（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-27-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-27（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> — 第46期 ｜ 🤖 AI 前沿（5 篇 arXiv，真实抓取于 2026-10-27） ✅ 本文件所有数值均<strong>逐一回对 arXiv 官方摘要</strong>（<code>export.arxiv.org/api/query?id_list=...</code>，2026-10-27 核验），非转述。</p></blockquote><hr><h2 id="科学日报-2026-10-27-harnessmm——把「重复推理」换成一纸可守卫的持久决定" tabindex="-1">科学日报 2026-10-27：HarnessMM——把「重复推理」换成一纸可守卫的持久决定 <a class="header-anchor" href="#科学日报-2026-10-27-harnessmm——把「重复推理」换成一纸可守卫的持久决定" aria-label="Permalink to &quot;科学日报 2026-10-27：HarnessMM——把「重复推理」换成一纸可守卫的持久决定&quot;">​</a></h2><blockquote><p>arXiv:2610.32813 ｜ HarnessMM: Recursive Self-Improvement for Harness Token Efficiency</p></blockquote><ul><li>问题：智能体 harness 在<strong>工具返回后反复调用推理</strong>，即便上一次调用早已定下下一步动作 —— 令牌被大量重复推理吃掉。</li><li>方法：<strong>HarnessMM（Harness Minus Minus）</strong> = <strong>受护的决定复用（guarded decision reuse）+ 递归自我改进（RSI）</strong>： <ul><li><strong>RSI</strong> 从训练反馈迭代精修配套 harness 配置，<strong>由验证集选出部署配置</strong>；</li><li>模型—工具边界上的<strong>控制器复用已解析的决定</strong>，在 <strong>actor 权重固定</strong>的前提下替代后续推理回调；</li><li><strong>可执行决定图（Executable Decision Graphs, EDG）</strong> 存<strong>确切动作、字面参数、因果依赖与公开守卫</strong>；</li><li><strong>Guarded Decision Reuse</strong> 由观察到的 receipt 激活这些持久决定；<strong>Certified Callback Substitution</strong> 经原生接口执行它们并记录慢回调的移除；</li><li><strong>新语义决定 / 证据不足 / 选择器弃权</strong>时，交回原 actor。</li></ul></li><li>结果（全部为摘要原值）： <ul><li><strong>HumanEval</strong>：<strong>Codex 成功率保持 90.82%</strong>，<strong>Tokens/task 从 66.72k 降到 47.02k（省 29.54%）</strong>；</li><li><strong>DeepSeek Harness</strong>：<strong>成功率 71.43% → 85.71%</strong>，<strong>Tokens/task 从 96.28k 降到 11.62k（省 87.93%）</strong>；</li><li><strong>MBPP 消融</strong>：比 single-use graphs <strong>成本低 26.91%</strong>、比 retained callbacks <strong>低 19.52%</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>ai-brain</code>）： <ol><li><strong>把「反复计算」固化成一纸</strong>受守卫的持久决定**（EDG）」= 从无状态走向有状态** —— 与 10-26 <code>Accordion</code>（一套参数一个深度旋钮）、10-25 <code>METTA</code>（时间尺度分解）同族：<strong>智能体效率提升的主线，是把『每次重生算一遍』改成『记住一个决定 + 守卫』。</strong></li><li><strong>「留一测试 / 验证集选配置」做决定准入 = 与 AI 外脑 <code>auto_link.py</code> 的准入门同源</strong> —— 改动只有在<strong>留出集上泛化</strong>才被接受。可写入 <code>topics/ai-brain/</code> 的「准入规则」：<strong>写入前先问：这条链接在别的样本上还成立吗？</strong></li></ol></li></ul><hr><h2 id="科学日报-2026-10-27-on-policy-self-training——只给「主题一句话」-模型自己出题自己练" tabindex="-1">科学日报 2026-10-27：On-Policy Self-Training——只给「主题一句话」，模型自己出题自己练 <a class="header-anchor" href="#科学日报-2026-10-27-on-policy-self-training——只给「主题一句话」-模型自己出题自己练" aria-label="Permalink to &quot;科学日报 2026-10-27：On-Policy Self-Training——只给「主题一句话」，模型自己出题自己练&quot;">​</a></h2><blockquote><p>arXiv:2610.32770 ｜ On-Policy Self-Training: Data-Free Self-Improvement in Large Language Models</p></blockquote><ul><li>问题：on-policy 自蒸馏能不靠更强外部教师做后训练，但既有方法仍<strong>依赖真值问答对 / 人工筛选题集或其它监督信号</strong>。</li><li>方法：把 on-policy 自蒸馏<strong>重构成自训练框架</strong> —— 由模型<strong>自生成问答对 + 特权推理示范（privileged reasoning demonstrations）<strong>驱动。<strong>只给粗粒度、高层级的主题描述</strong>，模型自行合成</strong>查询 + 特权推理轨迹的课程</strong>，<strong>不接触任何人工题面或答案</strong>，把监督推到极限。</li><li>结果：对<strong>完全合成的特权信息</strong>做自蒸馏，能让模型<strong>跨多领域提升，同时保留未自训练领域的能力</strong>；框架在<strong>文本与多模态</strong>域均成立，在<strong>标准语言基准 + 视觉问答（VQA）</strong> 上取得一致的自我改进。</li><li>洞察：<strong>自提升要成立的前提，是『自产的监督里带得有可定位的信号』（特权推理轨迹）</strong> —— 与 10-22 <code>Environment Duels</code>（解题力 ≠ 出题力）、10-20 <code>Self-Building Labs</code> 同族：<strong>瓶颈不是『能不能自产数据』，而是『自产的数据里有没有真正的对照/依据』。</strong></li></ul><hr><h2 id="科学日报-2026-10-27-换一个嵌入域——从单位球面挪到概率单纯形-模态鸿沟缩-97–99" tabindex="-1">科学日报 2026-10-27：换一个嵌入域——从单位球面挪到概率单纯形，模态鸿沟缩 97–99% <a class="header-anchor" href="#科学日报-2026-10-27-换一个嵌入域——从单位球面挪到概率单纯形-模态鸿沟缩-97–99" aria-label="Permalink to &quot;科学日报 2026-10-27：换一个嵌入域——从单位球面挪到概率单纯形，模态鸿沟缩 97–99%&quot;">​</a></h2><blockquote><p>arXiv:2610.32890 ｜ Closing the Modality Gap via Simplex-Constrained Representations</p></blockquote><ul><li>问题：CLIP / CLAP 等多模态对比模型能学到共享表征，但嵌入普遍存在顽固的<strong>模态鸿沟</strong>。</li><li>方法：<strong>纯几何</strong>解法 —— 把嵌入域从<strong>单位球面 S^{d−1}</strong> 换成<strong>概率单纯形 Δ^{d−1}</strong>。两者<strong>内蕴维度相同</strong>，但单纯形充当<strong>结构先验</strong>：<strong>非负、单位质量约束 = 跨模态标定</strong>，强制两个模态落进<strong>同一坐标系</strong>。只需挂<strong>轻量 softmax 适配器</strong>，用<strong>全变差（Total Variation）相似度</strong>替换余弦相似度。</li><li>结果：在<strong>五个多模态检索基准</strong>上把<strong>质心 ℓ₂ 鸿沟缩小 97–99%</strong>，检索性能<strong>匹配甚至超过</strong>标准无约束模型。</li><li>洞察：<strong>模态鸿沟可能主要不是『语义没对齐』，而是『坐标域选错了』</strong> —— 与 10-23「概念擦除与引导是同一算子的两面」、10-21「隐喻的几何」同族：<strong>当两个空间『看起来分开』，先问是不是坐标系的问题，而不是急着用数据去拉近它们</strong>；后者的代价是<strong>零训练</strong>。</li></ul><hr><h2 id="科学日报-2026-10-27-topklora——让可解释性内建进微调-一刀切掉后门" tabindex="-1">科学日报 2026-10-27：TopKLoRA——让可解释性内建进微调，一刀切掉后门 <a class="header-anchor" href="#科学日报-2026-10-27-topklora——让可解释性内建进微调-一刀切掉后门" aria-label="Permalink to &quot;科学日报 2026-10-27：TopKLoRA——让可解释性内建进微调，一刀切掉后门&quot;">​</a></h2><blockquote><p>arXiv:2610.32866 ｜ Interpretable sparse fine-tuning with TopKLoRA enables faithful circuit discovery</p></blockquote><ul><li>问题：在来源不明的数据上微调可能植入<strong>后门</strong>，而后门<strong>难定位、难移除、还能扛过安全训练</strong>；参数高效微调虽能捕获训练引入的全部变化，却<strong>不易解释</strong>。</li><li>方法：<strong>TopKLoRA</strong>（扩展自 Masiak 等 2025 的初步提案）—— 一种<strong>按设计可解释</strong>的 LoRA 变体：<strong>每个 token 只激活 k 个最大的适配器潜变量</strong>。与 SAE 不同，它<strong>纯按下游损失训练</strong>，优化压力<strong>激励学出功能上因果的潜变量</strong>。</li><li>结果：在「<strong>卧底智能体（sleeper-agent）后门</strong>」案例中，用投毒指令微调数据造出 <strong>gemma-2-2b、Qwen2.5-1.5B、Qwen2.5-7B</strong> 模型生物，对每个<strong>定位并消融一个对后门必要且充分的电路</strong>；稀疏电路比<strong>稠密 LoRA 基线小至多一个数量级</strong>，从而<strong>手术式消融恶意能力而不牺牲指令跟随</strong>。并给出用 TopKLoRA 潜变量 + 梯度路由构造<strong>带局部电路的模型生物</strong>来验证电路搜索的方法。</li><li>洞察：<strong>可解释性可以是「设计出来的」，而不必是「事后猜出来的」</strong> —— 与 10-23 <code>PhysiCalWorld</code>（交互编码为少量描述符）、10-25「隐喻的因果子空间」同族：<strong>当你想理解一次微调做了什么，先限制它『能改多少』。</strong></li></ul><hr><h2 id="科学日报-2026-10-27-企业级-rag-重构——先「组织」再「检索」-让歧义变成结构性的" tabindex="-1">科学日报 2026-10-27：企业级 RAG 重构——先「组织」再「检索」，让歧义变成结构性的 <a class="header-anchor" href="#科学日报-2026-10-27-企业级-rag-重构——先「组织」再「检索」-让歧义变成结构性的" aria-label="Permalink to &quot;科学日报 2026-10-27：企业级 RAG 重构——先「组织」再「检索」，让歧义变成结构性的&quot;">​</a></h2><blockquote><p>arXiv:2610.32851 ｜ Reimagining Enterprise RAG for Multi-Agent Systems: A Knowledge Layer That Organizes Before It Retrieves</p></blockquote><ul><li>问题：企业把智能体 AI 铺到软件开发生命周期，需要的是<strong>系统自身的行为逻辑</strong>而非给干系人看的文档。作者用<strong>七智能体重工程流水线</strong>，把 <strong>18 个服务的 241 个仓库</strong>处理成数千条描述范围/旅程/规则/验收标准的<strong>工件</strong>。但**「恢复出来」≠「可用」<strong>：<code>offer / eligibility / activation</code> 等实体在服务间</strong>共享同一套词汇、名字相关而运行上各异**，一个端到端旅程牵涉<strong>上千条近似但不许混淆的规则</strong>。</li><li>失败点：<strong>扁平向量检索失败</strong> —— 它会把<strong>另一个服务里的同款规则</strong>以高相似度返回，<strong>且不给任何出错信号</strong>。内容级本体不存在，而给每个复现实体都建关系<strong>比项目本身还贵</strong>。</li><li>方法：把<strong>本体放到工件层</strong>（每个工件保留生产者、组件、服务、域、类型等<strong>溯源信息</strong>，读内容前即消歧）—— 一个**「先组织再检索」的知识层**：<strong>自描述目录 + 稀疏元数据注册表 + 定义在工件（而非抽取实体）之上的导航超图</strong>。查询先解析到<strong>工件标识符</strong>，再以其<strong>约束向量搜索</strong>，于是「另一服务的竞争规则」<strong>根本不在候选里，而不是排在后面</strong>，消歧成为<strong>结构性而非统计性</strong>。</li><li>结果：<strong>一周内建成</strong>、按约定接纳新服务；支撑 <strong>100+ 生产缺陷</strong>的根因分析与修复（有开发者验证），并把 <strong>35 个发布回归失败</strong>归因到具体规则与服务。</li><li>洞察：<strong>「组织」发生在「检索」之前 = 与本库 AI 外脑的核心主张同构</strong> —— 本库 <code>topics/</code>（组织层）在先、<code>query_brain</code>（检索）在后正是这条路线；与 10-26「企业场景」、本库「存入即关联」一脉。判据：<strong>一个知识系统若检索质量差，第一嫌疑不是检索引擎，而是『组织层缺失』——先补组织，再调检索</strong>，这正是本库 <code>auto_link</code> 的存在理由。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第46期 AI 板块</p></blockquote><p>关键词：科学日报第46期、HarnessMM、guarded decision reuse 受护决定复用、RSI 递归自我改进、Executable Decision Graph 可执行决定图、Certified Callback Substitution、HumanEval Codex 90.82%、Tokens/task 66.72k→47.02k 省29.54%、DeepSeek Harness 71.43%→85.71%、96.28k→11.62k 省87.93%、MBPP 消融 26.91%/19.52%、留出集选配置=准入门、把每次重生算一遍改成记住一个决定；On-Policy Self-Training、OPST、自训练框架、自生成问答对、特权推理示范 privileged reasoning、只给粗粒度主题描述、无人工题面答案、保留未自训练域、文本+多模态、VQA、自提升要有可定位信号；Closing the Modality Gap、单纯形约束 simplex、单位球面 S^{d-1}→概率单纯形 Δ^{d-1}、非负单位质量=跨模态标定、轻量 softmax 适配器、全变差相似度 Total Variation、五基准质心 ℓ₂ 鸿沟降 97-99%、坐标域选错、零训练对齐；TopKLoRA、每token激活k个最大适配器潜变量、纯下游损失训练、功能因果潜变量、sleeper-agent 后门、gemma-2-2b、Qwen2.5-1.5B/7B、必要且充分电路、消融、稀疏电路小一个数量级、手术式消融不牺牲指令跟随、可解释性内建于设计；企业级 RAG、七智能体逆向工程、18服务241仓库、工件 artifact、扁平向量检索失败、无出错信号、内容级本体不存在、本体放到工件层、自描述目录、稀疏元数据注册表、工件级导航超图、查询解析到工件ID约束向量搜索、结构性而非统计性消歧、一周建成、100+生产缺陷、35回归失败、先组织再检索、组织层缺失先于检索引擎、auto_link 存在理由</p><p>关联：<code>topics/ai-system-architecture/science-daily-2026-10-26-ai.md</code>（Accordion / 非线性概念擦除 / Ariadne）、<code>topics/ai-system-architecture/science-daily-2026-10-25-ai.md</code>（EpiSEM-Bench / METTA / 反向谄媚）、<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-brain/index.md</code>、<code>topics/ai-brain/auto-link-quality-fixes.md</code></p>',26)])])}const h=t(e,[["render",i]]);export{p as __pageData,h as default};
